    def numberOfStableArrays(self, zero: int, one: int, limit: int) -> int:
        MOD = 10**9 + 7

        # Create 4D DP array: dp[z][o][last][run]
        # z: number of zeros used (0 to zero)
        # o: number of ones used (0 to one) 
        # last: last element (0 or 1)
        # run: current run length of last element (1 to limit)

        # Initialize a 4D array with dimensions (zero+1) x (one+1) x 2 x (limit+1)
        # Use nested list comprehensions to create proper dimensions
        dp = [[[[0 for _ in range(limit + 1)] for _ in range(one + 1)] 
               for _ in range(zero + 1)] for _ in range(2)]

        # Base cases: start with either 0 or 1
        if zero >= 1:
            dp[0][0][0][1] = 1

        if one >= 1:
            dp[0][0][1][1] = 1

        # Fill the DP table
        for z in range(zero + 1):
            for o in range(one + 1):
                for last in range(2):
                    for run in range(1, limit + 1):
                        if dp[z][o][last][run] == 0:
                            continue

                        # Try to add the same element (if we haven't reached limit)
                        if run < limit:
                            new_z = z + 1 if last == 0 else z
                            new_o = o + 1 if last == 1 else o
                            if new_z <= zero and new_o <= one:
                                new_run = run + 1
                                dp[new_z][new_o][last][new_run] = (dp[new_z][new_o][last][new_run] + dp[z][o][last][run]) % MOD

                        # Try to add a different element
                        other_last = 1 - last
                        new_z = z + 1 if other_last == 0 else z
                        new_o = o + 1 if other_last == 1 else o
                        if new_z <= zero and new_o <= one:
